CREATE TABLE "requirement_topic_entry_images" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(20) NOT NULL DEFAULT acp_generate_public_code(),
  "entry_id" bigint NOT NULL,
  "file_name" text NOT NULL,
  "mime_type" text NOT NULL,
  "byte_size" integer NOT NULL,
  "data_url" text NOT NULL,
  "sort_order" integer NOT NULL DEFAULT 0,
  "created_at" text NOT NULL,
  CONSTRAINT "ck_requirement_topic_entry_images_code" CHECK ("code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$'),
  CONSTRAINT "ck_requirement_topic_entry_images_mime" CHECK ("mime_type" IN ('image/png', 'image/jpeg', 'image/webp', 'image/gif')),
  CONSTRAINT "ck_requirement_topic_entry_images_size" CHECK ("byte_size" > 0 AND "byte_size" <= 2097152)
);
--> statement-breakpoint
CREATE UNIQUE INDEX "uq_requirement_topic_entry_images_code" ON "requirement_topic_entry_images" ("code");
--> statement-breakpoint
CREATE INDEX "idx_requirement_topic_entry_images_entry" ON "requirement_topic_entry_images" ("entry_id", "sort_order");
--> statement-breakpoint
CREATE TRIGGER "trg_requirement_topic_entry_images_code_immutable" BEFORE UPDATE OF "code" ON "requirement_topic_entry_images" FOR EACH ROW EXECUTE FUNCTION acp_prevent_code_update();
